def report(readline):
    n, capacity = map(int, readline().split())
    events = []
    for _ in range(n):
        time, client, size = readline().split()
        events.append((time, int(client), int(size)))
    used = 0
    totals = {}
    copies = []
    for time, client, size in sorted(events):
        totals[client] = totals.get(client, 0) + size
        if used + size > capacity:
            if time < '12:00:00':
                copies.append(used)
            used = 0
        used += size
    leader = min(totals, key=lambda client: (-totals[client], client))
    return leader, sum(sorted(copies, reverse=True)[:2])

